/**
 * Shared pill-string utilities used by flow-action-definition-plugin and step-instance-plugin.
 *
 * Pill strings look like "{{step[CID].record.name|string}}" or "{{action.desc|string}}".
 * These helpers strip the "|type" suffix (for element_mapping values) and collect
 * the type annotations (for label_cache).
 */

/** Regex for extracting step pill type annotations: {{step[CID].path|type}} */
export const STEP_PILL_TYPE_REGEX = /\{\{step\[([^\]]+)\]\.([^|}]+)(?:\|([^}]+))?\}\}/g

/** Regex for extracting action pill type annotations: {{action.path|type}} */
export const ACTION_PILL_TYPE_REGEX = /\{\{action\.([^|}]+)(?:\|([^}]+))?\}\}/g

/**
 * Strips the |type suffix from a pill string.
 * e.g., "{{step[CID].record.number|string}}" → "{{step[CID].record.number}}"
 *       "{{action.desc|string}}" → "{{action.desc}}"
 *
 * Called on individual pill strings (from resolveFieldToPillString),
 * never on concatenated multi-pill strings — so no `g` flag is needed.
 */
export function stripPillType(pill: string): string {
    return pill.replace(/\|[^}]+/, '')
}

/**
 * Extracts pill type annotations from a pill string and stores them in pillTypeMap.
 * Handles both step pills ({{step[CID].path|type}}) and action pills ({{action.path|type}}).
 * The collected types are used later when building the label_cache.
 */
export function collectPillTypes(pillString: string, pillTypeMap?: Map<string, string>): void {
    if (!pillTypeMap) {
        return
    }
    for (const match of pillString.matchAll(STEP_PILL_TYPE_REGEX)) {
        const [, cid, pillPath, dataType] = match
        if (cid && pillPath && dataType) {
            pillTypeMap.set(`${cid}::${pillPath}`, dataType)
        }
    }
    for (const match of pillString.matchAll(ACTION_PILL_TYPE_REGEX)) {
        const [, path, dataType] = match
        if (path && dataType) {
            pillTypeMap.set(`action::${path}`, dataType)
        }
    }
}
